/*
 * Compatibility stand-in, not GSAP. Pages generated by earlier versions of
 * nr_landingpage load this file and run scripts stored in the page that use
 * GSAP: the animation script the extension generated and, in creative mode,
 * scripts the LLM wrote. GSAP is no longer shipped (see Documentation/Usage).
 *
 * Every global the GSAP 3 files defined (gsap, ScrollTrigger, Observer,
 * TextPlugin, TweenMax, TimelineMax, the ease objects, ...) is an inert value:
 * it can be read, called, constructed, iterated and awaited without throwing,
 * and `await` gives a value that is inert too. Nothing is animated. Each call
 * is checked for what decides whether content is seen:
 *
 * - its first argument names the elements (selector, element, list);
 * - end values that show content are applied at once: opacity or autoAlpha
 *   above 0, a visibility other than hidden, and non-empty text (string or
 *   {value}), also inside css: {...}. to() and set() take them from every
 *   object argument, fromTo() from its last one, and from() from none, since
 *   its values are start values. Values that hide content are ignored;
 * - when the first argument is a plain object (a counter), its numeric
 *   properties are set to the end values;
 * - then functions passed as arguments or option values (onEnter,
 *   onComplete, onUpdate, context and matchMedia callbacks, ...) run once.
 *
 * gsap.utils.toArray() returns the elements, so loops over them run.
 * ScrollTrigger.min.js and TextPlugin.min.js only remain for the script tags
 * of those pages.
 */
(function () {
  'use strict';

  var called = typeof WeakSet === 'function' ? new WeakSet() : null;
  var inert;

  function permissive(object) {
    return new Proxy(object, {
      get: function (target, property) {
        return property in target ? target[property] : inert[property];
      }
    });
  }

  function elements(target) {
    var found = [];
    var collect = function (item, depth) {
      if (typeof item === 'string') {
        try {
          Array.prototype.push.apply(found, document.querySelectorAll(item));
        } catch (e) {
          // Not a selector, for example a media query.
        }
      } else if (item && item.nodeType === 1) {
        found.push(item);
      } else if (item && !isStandIn(item) && typeof item.length === 'number' && depth < 3) {
        Array.prototype.forEach.call(item, function (entry) { collect(entry, depth + 1); });
      }
    };
    collect(target, 0);
    return found;
  }

  function reveal(nodes, vars) {
    if (!vars || typeof vars !== 'object' || nodes.length === 0) {
      return;
    }
    var text = vars.text;
    if (text && typeof text === 'object') {
      text = text.value;
    }
    nodes.forEach(function (element) {
      if (typeof text === 'string' && text !== '') {
        element.textContent = text;
      }
      if (Number(vars.autoAlpha) > 0) {
        element.style.opacity = String(vars.autoAlpha);
        element.style.visibility = 'visible';
      }
      if (Number(vars.opacity) > 0) {
        element.style.opacity = String(vars.opacity);
      }
      if (typeof vars.visibility === 'string' && vars.visibility !== 'hidden') {
        element.style.visibility = vars.visibility;
      }
    });
  }

  function runOnce(callback, argument) {
    if (called) {
      if (called.has(callback)) {
        return;
      }
      called.add(callback);
    }
    try {
      callback(argument);
    } catch (e) {
      // A failing callback must not stop the rest of the stored script.
    }
  }

  function isPlainObject(value) {
    return value !== null && typeof value === 'object' && value.nodeType === undefined
      && typeof value.length !== 'number';
  }

  // End values: to() and set() take them from every object argument,
  // fromTo() from its last one, from() from none (its values are start values).
  function endValues(args, mode) {
    var objects = [];
    for (var i = 1; i < args.length; i++) {
      if (isPlainObject(args[i])) {
        objects.push(args[i]);
      }
    }
    if (mode === 'from') {
      return [];
    }
    if (mode === 'fromTo') {
      return objects.slice(-1);
    }
    return objects;
  }

  function assignNumbers(target, vars) {
    Object.keys(vars).forEach(function (key) {
      if (typeof target[key] === 'number' && typeof vars[key] === 'number' && isFinite(vars[key])) {
        target[key] = vars[key];
      }
    });
  }

  function handle(args, mode) {
    var nodes = elements(args[0]);
    endValues(args, mode).forEach(function (vars) {
      reveal(nodes, vars);
      reveal(nodes, vars.css);
      if (isPlainObject(args[0])) {
        assignNumbers(args[0], vars);
      }
    });
    var argument = permissive(nodes.slice());
    var visit = function (value, depth) {
      if (typeof value === 'function' && !isStandIn(value)) {
        runOnce(value, argument);
      } else if (isPlainObject(value) && depth < 3) {
        Object.keys(value).forEach(function (key) { visit(value[key], depth + 1); });
      }
    };
    for (var i = 0; i < args.length; i++) {
      visit(args[i], 0);
    }
    return inert;
  }

  var standIns = typeof WeakSet === 'function' ? new WeakSet() : null;

  function isStandIn(value) {
    return standIns !== null && standIns.has(value);
  }

  var settled;
  var modes = {};

  function make(mode, thenable) {
    var proxy = new Proxy(function () {}, {
      get: function (target, property) {
        if (property === 'then') {
          if (!thenable) {
            return undefined;
          }
          // Settle at once with a value that is not thenable itself, so
          // `await tween` neither loops nor yields undefined.
          return function (onFulfilled) {
            if (typeof onFulfilled === 'function') {
              runOnce(onFulfilled, settled);
            }
            return Promise.resolve(settled);
          };
        }
        if (property === 'toArray') {
          return function (list) { return permissive(elements(list)); };
        }
        if (property === Symbol.toPrimitive) {
          return function () { return 0; };
        }
        if (property === Symbol.iterator) {
          return function () { return [][Symbol.iterator](); };
        }
        if (typeof property === 'symbol') {
          return undefined;
        }
        if (property === 'from' || property === 'staggerFrom') {
          return modes.from;
        }
        if (property === 'fromTo' || property === 'staggerFromTo') {
          return modes.fromTo;
        }
        return inert;
      },
      apply: function (target, self, args) {
        return handle(args, mode);
      },
      construct: function (target, args) {
        handle(args, mode);
        return inert;
      }
    });
    if (standIns !== null) {
      standIns.add(proxy);
    }
    return proxy;
  }

  inert = make('to', true);
  settled = make('to', false);
  modes.from = make('from', true);
  modes.fromTo = make('fromTo', true);

  [
    'gsap', 'ScrollTrigger', 'TextPlugin', 'CSSPlugin',
    'TweenLite', 'TweenMax', 'TimelineLite', 'TimelineMax',
    'Back', 'Bounce', 'Circ', 'Cubic', 'Elastic', 'Expo', 'Linear', 'Power0', 'Power1', 'Power2',
    'Power3', 'Power4', 'Quad', 'Quart', 'Quint', 'Sine', 'SteppedEase', 'Strong',
    'Observer', 'AttrPlugin', 'EndArrayPlugin', 'ModifiersPlugin', 'RoundPropsPlugin', 'SnapPlugin',
    'gsapVersions'
  ].forEach(function (name) {
    if (window[name] === undefined) {
      window[name] = inert;
    }
  });
})();
